{
    "warehouse_id": "{{warehouse_id}}",
    "statement": "SELECT MedrioUserId, FirstName, LastName, Email, CourseId, CourseName, CourseStatus, CourseRegDate, CourseCompletionDate, IsCompleted, COUNT(*) AS dup_count FROM edc_etl_dev_bran_04.gold.elearning_status GROUP BY MedrioUserId, FirstName, LastName, Email, CourseId, CourseName, CourseStatus, CourseRegDate, CourseCompletionDate, IsCompleted HAVING COUNT(*) > 1;"
}

{
  "warehouse_id": "{{warehouse_id}}",
  "statement": "WITH d AS (SELECT MedrioUserId, CourseId, DATEDIFF(CourseCompletionDate, CourseRegDate) AS days FROM edc_etl_dev_bran_04.gold.elearning_status WHERE CourseCompletionDate IS NOT NULL AND CourseRegDate IS NOT NULL), q AS (SELECT percentile_approx(days, 0.25) AS q1, percentile_approx(days, 0.75) AS q3 FROM d), b AS (SELECT q1, q3, (q3 - q1) AS iqr, (q1 - 1.5 * (q3 - q1)) AS lower_bound, (q3 + 1.5 * (q3 - q1)) AS upper_bound FROM q) SELECT d.MedrioUserId, d.CourseId, d.days, b.lower_bound, b.upper_bound FROM d CROSS JOIN b WHERE d.days < b.lower_bound OR d.days > b.upper_bound;"
}

{
    "warehouse_id": "{{warehouse_id}}",
