}

{
  "warehouse_id": "{{warehouse_id}}",
  "statement": "WITH u AS (SELECT MedrioUserId, COUNT(DISTINCT CourseId) AS course_count FROM edc_etl_dev_bran_04.gold.elearning_status GROUP BY MedrioUserId), q AS (SELECT percentile_approx(course_count, 0.25) AS q1, percentile_approx(course_count, 0.75) AS q3 FROM u), b AS (SELECT q1, q3, (q3 - q1) AS iqr, (q3 + 1.5 * (q3 - q1)) AS upper_bound FROM q) SELECT u.MedrioUserId, u.course_count, b.upper_bound FROM u CROSS JOIN b WHERE u.course_count > b.upper_bound;"
}

